// ================= chapter 1 — LIVE: World Cup 2024 semi-final, Tashkent, Argentina v France. Only confirmed things: the arena and the
// teams at kick-off (0–0, 00:00; nobody on court is identified), a broadcast player graphic (Gauna, No. 8; his three logged shots), then
// (cut) the 3–2 final whistle. No play of the match is staged. Local u = metres from France's goal (Argentina attack u → 0; inferred). ======
const C1={ko:A(0,'The 2024'),tash:A(0,'in Tashkent'),play:A(0,'Argentina play'),num:A(0,'Number eight'),name:A(0,'Luciano Gauna'),tries:A(0,'He tries'),shots:A(0,'three shots'),win:A(0,'Argentina win'),tt:A(0,'three two'),fin:A(0,'reach the final'),end:AUTH[0].seconds};
/** one whip pan (a cut in time): kick-off → the final whistle */
const V0=C1.win-.14,V1=V0+.26,VM=(V0+V1)/2;
const KO_ARG:[number,number][]=[[27.4,.4],[23.6,-4.2],[23.1,5.4],[20.9,.7]];
const KO_FRA:[number,number][]=[[18.4,-2.2],[16.2,4.6],[16.4,-5],[13.2,.3]];
const idle=(t:number,ph:number)=>{const b=Math.sin(t*5+ph*6)*.5+.5;return posed({lHipF:16,rHipF:16,lKnee:24+8*b,rKnee:22+8*b,lHipA:10,rHipA:10,lean:12,neckP:6,lShA:18,rShA:18,lElb:36,rElb:36,air:.02*b});};
