const liveArg=(i:number):LGen=>T=>{
 if(T<VM){const p=KO_ARG[i];return{pose:idle(T,i),yaw:Math.PI,u:p[0],v:p[1]};}
 const spot=([[FIN[0]-1,FIN[1]+.9],[FIN[0]+.9,FIN[1]+1.1],[FIN[0]-1.1,FIN[1]-.5],[FIN[0]+1.2,FIN[1]-.6]] as [number,number][])[i];
 return{pose:celebrate((T-VM)*1.1+i*.37,{kind:i===3?'run':'arms'}),yaw:-Math.PI/2+[.3,-.2,.5,-.4][i],u:spot[0],v:spot[1]};};
/** France at the final whistle: heads down, hands on hips */
const DOWN=posed({lHipF:8,rHipF:8,lKnee:14,rKnee:14,lean:18,neckP:44,lShA:30,rShA:30,lShF:-20,rShF:-20,lElb:110,rElb:110});
const liveFra=(i:number):LGen=>T=>{if(T<VM){const p=KO_FRA[i];return{pose:idle(T,i+.37),yaw:0,u:p[0],v:p[1]};}
 const base=([[22.2,5.8],[24.4,-6.6],[26.2,2.2],[12.6,7.4]] as [number,number][])[i];
 return{pose:DOWN,yaw:Math.PI*.8,u:base[0],v:base[1]};};
const liveGK:LGen=T=>T<VM?{pose:keeperSet(T*1.3),yaw:0,u:.7,v:0}:{pose:DOWN,yaw:.4,u:.9,v:-.5};
const liveCam=(T:number)=>({x:key(T,mono([[0,1.2],[C1.play,2.6],[C1.num,3.2],[V0,3.4],[V1,-3.4],[C1.end,-3]]),easeInOutSine),
 zoom:key(T,mono([[0,.56],[C1.tash,.6],[C1.num,.64],[V0,.66],[V1,.94],[C1.tt,.98],[C1.end,1.02]]),easeInOutSine),
 y:key(T,mono([[0,1060],[C1.play,1040],[V0,1030],[V1,880],[C1.end,870]]),easeInOutSine)});
/** seven-segment digits on the arena scoreboard */
const SEG:Record<string,number[]>={'0':[0,1,2,4,5,6],'1':[2,5],'2':[0,2,3,4,6],'3':[0,2,3,5,6],'4':[1,2,3,5],'5':[0,1,3,5,6],'6':[0,1,3,4,5,6],'7':[0,2,5],'8':[0,1,2,3,4,5,6],'9':[0,1,2,3,5,6]};
